(7747543, 1279562, 100831, '<td valign="top">You got this! And the light is perfect!</td>', 'You got this! And the light is perfect!', '2023-06-04 12:59:14.000000', NULL, 1),
(7747546, 1279568, 100831, '<td valign="top">So much to take in. Starting with all the verticals ... a treasure of a photograph.</td>', 'So much to take in. Starting with all the verticals ... a treasure of a photograph.', '2023-06-04 13:01:40.000000', NULL, 1),
(7748378, 1278601, 67258, '<td valign="top">I have revisited this a few times. There is something of your stylistic representation that does appeal, but on balance I find the image just too flat, giving the church the appearance of being pasted on to the background. Nonetheless, a lovely scene and I suspect a cracking base photo.</td>', 'I have revisited this a few times. There is something of your stylistic representation that does appeal, but on balance I find the image just too flat, giving the church the appearance of being pasted on to the background. Nonetheless, a lovely scene and I suspect a cracking base photo.', '2023-06-07 07:31:37.000000', NULL, 1),
(7748379, 1279387, 67258, '<td valign="top">This is MY place!  A really good photo that is surprisingly hard to get. I suspect you have had to do a fair amount of cloning of other visitors - it has been really busy lately!</td>', 'This is MY place!  A really good photo that is surprisingly hard to get. I suspect you have had to do a fair amount of cloning of other visitors - it has been really busy lately!', '2023-06-07 07:33:43.000000', NULL, 1),
(7748381, 1279567, 67258, '<td valign="top">A thoroughly pleasing and different representation of Stonehenge. A caveat though - not keen on your treatment of the sky:  there are a couple of places where the brush strokes fall wrong, most notably immediately adjacent to the stones.</td>', 'A thoroughly pleasing and different representation of Stonehenge. A caveat though - not keen on your treatment of the sky:  there are a couple of places where the brush strokes fall wrong, most notably immediately adjacent to the stones.', '2023-06-07 07:39:27.000000', NULL, 1),
(7748383, 1279542, 67258, '<td valign="top">Pleasing and good control of tricky light. Might benefit from some perspective adjustment.</td>', 'Pleasing and good control of tricky light. Might benefit from some perspective adjustment.', '2023-06-07 07:40:16.000000', NULL, 1),
(7748714, 1279567, 147314, '<td valign="top">I do like the editing. And that rook is a nice addition.</td>', 'I do like the editing. And that rook is a nice addition.', '2023-06-08 16:30:01.000000', NULL, 1),
(7748715, 1279270, 147314, '<td valign="top">Love the contrast and especially that light coming from above. In my top 3!</td>', 'Love the contrast and especially that light coming from above. In my top 3!', '2023-06-08 16:30:44.000000', NULL, 1),
